#define main ExistingBudgetMain
#import "AIRuntimeBudgetTests.m"
#undef main
static NSArray *ProjectUsage(NSString *project){__block NSArray *records=nil;dispatch_semaphore_t done=dispatch_semaphore_create(0);[[TFAIUsageStore shared] read:^(NSArray *all,NSString *error){records=[all filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *r,NSDictionary *bindings){return [r[@"project"] isEqual:project];}]];dispatch_semaphore_signal(done);}];Check(dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,10*NSEC_PER_SEC))==0,@"ledger writes completed");return records;}
int main(){@autoreleasepool{
 NSString *project=NSUUID.UUID.UUIDString;id runtime=TFAICreateRuntime(@"/tmp/fixture",project,nil);[runtime activateSession:@"usage-session"];
 [runtime setNextConnection:@{@"id":@"connection-A",@"name":@"A",@"model":@"model-A",@"protocol":@"chat"}];requests=0;
 FixtureTransport=^(NSArray *messages,NSArray *tools,TFAIEvent event){event(@{@"type":@"usage",@"usage":@{@"prompt_tokens":@(requests*100),@"completion_tokens":@10,@"prompt_tokens_details":@{@"cached_tokens":@20}}});if(requests==1){event(@{@"type":@"tool_call",@"id":@"usage-tool",@"name":@"read_file",@"arguments":@{@"path":@"Fixture.m"}});}else{event(@{@"type":@"usage",@"usage":@{@"completion_tokens":@10}});event(@{@"type":@"text",@"text":@"done"});}event(@{@"type":@"done"});};
 [runtime send:@[@{@"role":@"user",@"content":@"fixture"}] session:@"usage-session"];NSArray *records=ProjectUsage(project);NSDictionary *totals=TFAIUsageTotals(records);Check(records.count==2&&[totals[@"input"] isEqual:@300]&&[totals[@"output"] isEqual:@20],@"one ledger row per real round, duplicate usage not summed");
 [runtime setNextConnection:@{@"id":@"connection-B",@"name":@"B",@"model":@"model-B",@"protocol":@"anthropic"}];FixtureTransport=^(NSArray *m,NSArray *t,TFAIEvent e){e(@{@"type":@"usage",@"usage":@{@"input_tokens":@40,@"cache_read_input_tokens":@20}});e(@{@"type":@"usage",@"usage":@{@"output_tokens":@5}});e(@{@"type":@"text",@"text":@"done"});e(@{@"type":@"done"});};[runtime send:@[@{@"role":@"user",@"content":@"switch"}] session:@"usage-session"];records=ProjectUsage(project);BOOL attributed=NO;for(NSDictionary *r in records)if([r[@"connection_id"] isEqual:@"connection-B"])attributed=[r[@"connection_model"] isEqual:@"model-B"]&&[r[@"counts"][@"input"] isEqual:@60];Check(attributed&&[TFAIUsageTotals(records)[@"sessions"] isEqual:@1],@"provider switch preserves session and attributes actual model");
 FixtureTransport=^(NSArray *m,NSArray *t,TFAIEvent e){e(@{@"type":@"usage",@"usage":@{@"input_tokens":@12}});};[runtime send:@[@{@"role":@"user",@"content":@"cancel"}] session:@"usage-session"];[runtime stop];records=ProjectUsage(project);BOOL stopped=NO;for(NSDictionary *r in records)if([r[@"status"] isEqual:@"stopped"])stopped=[r[@"counts"][@"input"] isEqual:@12];Check(stopped,@"cancel retains already reported input");
 NSLog(@"Usage actual runtime integration passed");return 0;
}}
